"""Ordered generator evaluator boundary."""
import json
import math

from .ast import Add, Array, Comma, Filter, Format, Identity, Iterate, Literal, Limit, Node, Pipe, Raise, StringTemplate
from .errors import RuntimeError
from .runtime import JsonValue, ValueStream, identity_stream


def evaluate(program: Filter, value: JsonValue) -> ValueStream:
    """Evaluate one input as an ordered stream of output values."""
    if isinstance(program, Node):
        yield from _node(program, value, {})
        return
    if isinstance(program, Identity):
        yield from identity_stream(value)
        return
    if isinstance(program, Iterate):
        if isinstance(value, list):
            yield from value
        elif isinstance(value, dict):
            yield from value.values()
        else:
            raise RuntimeError("cannot iterate over value")
        return
    if isinstance(program, Literal):
        yield program.value
        return
    if isinstance(program, Pipe):
        for intermediate in evaluate(program.left, value): yield from evaluate(program.right, intermediate)
        return
    if isinstance(program, Add):
        left = list(evaluate(program.left, value))
        right = list(evaluate(program.right, value))
        for first in left:
            for second in right:
                if isinstance(first, (int, float)) and isinstance(second, (int, float)):
                    yield first + second
                elif isinstance(first, str) and isinstance(second, str): yield first + second
                elif first is None: yield second
                elif second is None: yield first
                else: raise RuntimeError("cannot add values")
        return
    if isinstance(program, StringTemplate):
        pieces: list[str] = []
        for part in program.parts:
            pieces.append(part if isinstance(part, str) else "".join(_stringify(x) for x in evaluate(part, value)))
        yield "".join(pieces)
        return
    if isinstance(program, Format):
        if program.template is None: yield _apply_format(program.name, value)
        else:
            pieces: list[str] = []
            for part in program.template.parts:
                if isinstance(part, str): pieces.append(part)
                else:
                    pieces.extend(_apply_format(program.name, item) for item in evaluate(part, value))
            yield "".join(pieces)
        return
    if isinstance(program, Comma):
        yield from evaluate(program.left, value)
        yield from evaluate(program.right, value)
        return
    if isinstance(program, Raise):
        raise RuntimeError(program.message)
    if isinstance(program, Array):
        yield list(evaluate(program.expression, value))
        return
    if isinstance(program, Limit):
        outputs = iter(evaluate(program.expression, value))
        for _ in range(program.count):
            try:
                yield next(outputs)
            except StopIteration:
                break
        return
    raise RuntimeError("unknown compiled filter")

def _node(node: Node, value: object, env: dict[str, object]) -> ValueStream:
    op, a = node.operation, node.arguments
    if op == "identity": yield value
    elif op == "literal":
        text=a[0]; special={"true":True,"false":False,"null":None,"nan":float("nan"),"infinite":float("inf"),"-infinite":float("-inf"),"-nan":float("nan")}; yield special[text] if text in special else json.loads(text)
    elif op == "string": yield _decode_string(a[0], value, env)
    elif op == "format": yield _apply_format(a[0], value)
    elif op == "format_template": yield _decode_string(a[1], value, env).replace(_decode_string(a[1], value, env), _apply_format(a[0], value))
    elif op == "var":
        if a[0] not in env: raise RuntimeError(f"variable ${a[0]} is not defined")
        yield env[a[0]]
    elif op == "bind":
        for item in _node(a[0], value, env):
            bound=dict(env); _bind_pattern(a[1], item, bound)
            yield from _node(a[2], item, bound)
    elif op == "field": yield _index(value, a[0])
    elif op == "index":
        for base in _node(a[0],value,env): yield _index(base,a[1])
    elif op == "iterate":
        for base in _node(a[0],value,env):
            if isinstance(base,dict): yield from base.values()
            elif isinstance(base,list): yield from base
            else: raise RuntimeError("cannot iterate over value")
    elif op in ("indexexpr","slice"):
        for base in _node(a[0],value,env):
            if op=="slice":
                start=_one(a[1],base,env); end=None if a[2] is None else _one(a[2],base,env); yield base[int(start) if start is not None else 0:int(end) if end is not None else None]
            else: yield _index(base,_one(a[1],base,env))
    elif op == "array": yield [] if a[0] is None else list(_node(a[0],value,env))
    elif op == "object":
        result={}
        for key, expr in a[0]: result[str(_one(key,value,env))]=_one(expr,value,env)
        yield result
    elif op == "binary": yield from _binary(a[0],a[1],a[2],value,env)
    elif op == "unary":
        x=_one(a[1],value,env); yield -x
    elif op == "optional":
        try: yield from _node(a[0],value,env)
        except RuntimeError: return
    elif op == "if":
        branch=a[1] if _truth(_one(a[0],value,env)) else a[2]; yield from _node(branch,value,env)
    elif op == "try":
        try: yield from _node(a[0],value,env)
        except RuntimeError as error:
            if a[1] is not None: yield from _node(a[1],str(error),env)
    elif op == "label":
        try: yield from _node(a[1], value, {**env, '__label__': a[0]})
        except _Break as exc:
            if exc.name != a[0]: raise
    elif op == "break":
        raise _Break(a[0])
    elif op in ("reduce", "foreach"):
        states=list(_node(a[0], value, env)); initial=list(_node(a[2], value, env))
        currents=initial
        for item in states:
            next_currents=[]
            for current in currents:
                bound=dict(env); _bind_pattern(a[1], item, bound)
                next_currents.extend(_node(a[3], current, bound))
            currents=next_currents
            if op == "foreach":
                if a[4] is None:
                    yield from currents
                else:
                    for result in currents: yield from _node(a[4], result, env)
        if op=="reduce": yield from currents
    elif op == "call": yield from _call(a[0],a[1],value,env)
    elif op == "def":
        env.setdefault('__funcs__',{})[a[0]]=(a[1],a[2])
        yield value
    elif op == "defprog":
        funcs=dict(env.get('__funcs__',{})); funcs[a[0].arguments[0]]=(a[0].arguments[1],a[0].arguments[2])
        yield from _node(a[1],value,{**env,'__funcs__':funcs})
    elif op == "unsupported": raise RuntimeError("unsupported syntax")

class _Break(Exception):
    def __init__(self, name): self.name=name

def _bind_pattern(pattern, value, env):
    op, args=pattern.operation, pattern.arguments
    if op=='pattern_alt':
        first, second=args
        if first.operation=='pattern_object' and not isinstance(value,dict): return _bind_pattern(second,value,env)
        if first.operation=='pattern_array' and not isinstance(value,list): return _bind_pattern(second,value,env)
        return _bind_pattern(first,value,env)
    if op=='pattern_var': env[args[0]]=value
    elif op=='pattern_array':
        for i,p in enumerate(args[0]): _bind_pattern(p, value[i] if isinstance(value,list) and i<len(value) else None, env)
    elif op=='pattern_object':
        for key,p in args[0]: _bind_pattern(p, value.get(key) if isinstance(value,dict) else None, env)

def _one(node, value, env):
    vals=list(_node(node,value,env)); return vals[0] if vals else None
def _truth(x): return x is not None and x is not False
def _index(v,k):
    if isinstance(v,dict): return v.get(str(k))
    if isinstance(v,list): return v[int(k)] if -len(v)<=int(k)<len(v) else None
    raise RuntimeError("cannot index value")
def _binary(op,left,right,value,env):
    if op==',': yield from _node(left,value,env); yield from _node(right,value,env); return
    if op=='|':
        for x in _node(left,value,env): yield from _node(right,x,env)
        return
    if op in ('=', '|=', '+=', '-=', '*=', '/=', '%=', '//='):
        paths = _paths(left, value, env)
        replacements = [value] if op == '|=' else list(_node(right, value, env))
        for replacement in replacements:
            result = value
            for path in paths:
                old = _get_path(result, path)
                new = replacement if op == '=' else _one(right, old, env)
                if op not in ('=', '|='):
                    new = _arithmetic(op[0], old, replacement)
                result = _set_path(result, path, new)
            if paths: yield result
        return
    ls=list(_node(left,value,env)); rs=list(_node(right,value,env))
    for x in ls:
      for y in rs:
        if op=='+': yield y if x is None else x if y is None else x+y
        elif op=='-': yield x-y
        elif op=='*': yield x*y
        elif op=='/':
            if y==0: raise RuntimeError("division by zero")
            yield x/y
        elif op=='%': yield x%y
        elif op in ('==','!=','<','>','<=','>='): yield {'==':x==y,'!=':x!=y,'<':x<y,'>':x>y,'<=':x<=y,'>=':x>=y}[op]
        elif op in ('and','or'): yield (_truth(x) and _truth(y)) if op=='and' else (_truth(x) or _truth(y))
        elif op=='//': yield x if _truth(x) else y
        else: yield x

def _arithmetic(op, left, right):
    if op == '+': return left + right
    if op == '-': return left - right
    if op == '*': return left * right
    if op == '/': return left / right
    if op == '%': return left % right
    return right

def _paths(node, value, env):
    op, args = node.operation, node.arguments
    if op == 'identity': return [()]
    if op == 'field': return [(args[0],)]
    if op == 'index': return [p + (args[1],) for p in _paths(args[0], value, env)]
    if op == 'indexexpr':
        return [p + (key,) for p in _paths(args[0], value, env) for key in _node(args[1], value, env)]
    if op == 'iterate':
        result = []
        for p in _paths(args[0], value, env):
            current = _get_path(value, p)
            if isinstance(current, list): result.extend(p + (i,) for i in range(len(current)))
            elif isinstance(current, dict): result.extend(p + (k,) for k in current)
        return result
    return []

def _get_path(value, path):
    current = value
    for key in path:
        if isinstance(current, dict): current = current.get(str(key))
        elif isinstance(current, list):
            index = int(key); current = current[index] if -len(current) <= index < len(current) else None
        else: return None
    return current

def _set_path(value, path, replacement):
    if not path: return replacement
    if isinstance(value, dict):
        result = dict(value); key = str(path[0]); result[key] = _set_path(result.get(key), path[1:], replacement); return result
    if isinstance(value, list):
        result = list(value); index = int(path[0]); index = index + len(result) if index < 0 else index
        while index >= len(result): result.append(None)
        result[index] = _set_path(result[index], path[1:], replacement); return result
    return {str(path[0]): _set_path(None, path[1:], replacement)}
def _call(name,args,value,env):
    if not args and name in env:
        yield env[name]; return
    if name in env.get('__funcs__',{}):
        params,body=env['__funcs__'][name]
        if not args:
            yield from _node(body,value,env); return
        # jq arguments are filters evaluated against the caller input.
        vals=[_one(arg,value,env) for arg in args]

"""Application-facing interpreter orchestration."""

import json
from collections.abc import Iterable, Iterator

from .evaluator import evaluate
from .parser import parse
from .runtime import JsonValue


class Interpreter:
    """Compile once, then evaluate each JSON input in order."""

    def __init__(self, program: str) -> None:
        self._compiled = parse(program)

    def run(self, inputs: Iterable[JsonValue]) -> Iterator[JsonValue]:
        """Yield every output, preserving input and generator ordering."""
        for value in inputs:
            yield from evaluate(self._compiled, value)


def parse_input(line: str) -> JsonValue:
    """Decode one JSON input value."""
    return json.loads(line.lstrip("\ufeff"), parse_constant=_parse_json_constant)


def parse_inputs(text: str) -> Iterator[JsonValue]:
    """Decode every whitespace-separated JSON value in an input stream.

    ``jq`` accepts JSON values separated by arbitrary whitespace, so a value may
    span multiple physical lines.  ``raw_decode`` preserves the boundary
    between successive values without requiring a non-standard JSON parser.
    """
    decoder = json.JSONDecoder(parse_constant=_parse_json_constant)
    position = 0
    while True:
        while position < len(text) and text[position].isspace():
            position += 1
        if position >= len(text):
            return
        if position == 0 and text.startswith("\ufeff"):
            position += 1
            continue
        value, position = decoder.raw_decode(text, position)
        yield value


def _parse_json_constant(value: str) -> float:
    """Decode jq's accepted non-standard numeric constants."""
    return {"NaN": float("nan"), "Infinity": float("inf"),
            "-Infinity": float("-inf")}[value]
"""Precedence-aware jq expression parser."""
import json
import re
from dataclasses import dataclass
from .ast import Filter, Node, StringTemplate, Format
from .errors import CompileError
from .lexer import tokenize

@dataclass(frozen=True)
class T: text: str
OPS=("//=","?//","!=","==","|=","+=","-=","*=","/=","%=","<=",">=","..","//")
PREC={",":1,"|":2,"=":3,"|=":3,"+=":3,"-=":3,"*=":3,"/=":3,"%=":3,"//=":3,"//":4,"or":5,"and":6,"==":7,"!=":7,"<":7,">":7,"<=":7,">=":7,"+":8,"-":8,"*":9,"/":9,"%":9}

def lex(s: str) -> list[T]:
    s=re.sub(r"#[^\n]*","",s); out=[]; i=0
    while i<len(s):
        if s[i].isspace(): i+=1; continue
        if s[i]=='"':
            a=i; i+=1; esc=False
            while i<len(s):
                c=s[i]; i+=1
                if esc: esc=False
                elif c=='\\': esc=True
                elif c=='"': break
            else: raise CompileError("unterminated string")
            out.append(T(s[a:i])); continue
        op=next((x for x in OPS if s.startswith(x,i)),None)
        if op: out.append(T(op)); i+=len(op); continue
        m=re.match(r"(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?",s[i:])
        if m: out.append(T(m.group())); i+=len(m.group()); continue
        m=re.match(r"(?:[A-Za-z_][A-Za-z_0-9]*::)*[A-Za-z_][A-Za-z_0-9]*",s[i:])
        if m: out.append(T(m.group())); i+=len(m.group()); continue
        if s[i]=='$':
            m=re.match(r"\$[A-Za-z_][A-Za-z_0-9]*(?:::[A-Za-z_][A-Za-z_0-9]*)*",s[i:])
            if not m: raise CompileError("invalid binding")
            out.append(T(m.group())); i+=len(m.group()); continue
        if s[i]=='.' and i+1<len(s) and re.match(r"[A-Za-z_]",s[i+1]):
            m=re.match(r"\.[A-Za-z_][A-Za-z_0-9]*",s[i:]); out.append(T(m.group())); i+=len(m.group()); continue
        if s[i]=='@':
            m=re.match(r"@[A-Za-z_][A-Za-z_0-9]*",s[i:])
            if not m: raise CompileError("invalid format")
            out.append(T(m.group())); i+=len(m.group()); continue
        if s[i] in ".?=;,:|+-*/%$<>()[]{}": out.append(T(s[i])); i+=1; continue
        raise CompileError("unexpected character")
    out.append(T("<eof>")); return out

class Parser:
    def __init__(self,s:str): self.t=lex(s); self.i=0
    def p(self): return self.t[self.i].text
    def take(self,x=None):
        v=self.p()
        if x is not None and v!=x: raise CompileError(f"expected {x}")
        self.i+=1; return v
    def parse(self):
        if self.p()=="<eof>": raise CompileError("empty program")
        x=self.expr(0)
        while self.p()==';': self.take()
        if self.p()!='<eof>': raise CompileError("unexpected token")
        return x
    def expr(self,n):
        x=self.prefix()
        # Binding is a query construct, below all ordinary operators.
        if self.p()=='as' and n <= 2:
            self.take('as'); pattern=self.pattern(); self.take('|')
            return Node('bind',(x,pattern,self.expr(0)))
        while self.p() in PREC and PREC[self.p()]>=n:
            op=self.take(); q=PREC[op]; x=Node("binary",(op,x,self.expr(q if op in ("=","|=","+=","-=","*=","/=","%=","//=") else q+1)))
        if self.p()=='as' and n <= 2:
            self.take('as'); pattern=self.pattern(); self.take('|')
            return Node('bind',(x,pattern,self.expr(0)))
        return x
    def prefix(self):
        t=self.p()
        if t=='-': self.take(); return Node('unary',('-',self.expr(10)))
        if t=='if': return self.if_expr()
        if t in ('try','reduce','foreach','label','def','module','import','include'): return self.control(t)
        if t=='(': self.take(); x=self.expr(0); self.take(')'); return self.post(x)
        if t=='[':
            self.take()
            if self.p()==']': x=Node('array',(None,))
            else:
                parts=[self.expr(2)]
                while self.p()==',': self.take(); parts.append(self.expr(2))
                combined=parts[0]
                for part in parts[1:]: combined=Node('binary',(',',combined,part))
                x=Node('array',(combined,))
            self.take(']'); return self.post(x)
        if t=='{': return self.object()
        if t=='.': self.take(); return self.post(Node('identity'))
        if t.startswith('.'): self.take(); return self.post(Node('field',(t[1:],)))
        if t.startswith('$'): self.take(); return Node('var',(t[1:],))
        if t.startswith('"'): self.take(); return self.post(Node('string',(t,)))
        if t.startswith('@'): self.take(); return self.post(Node('format',(t[1:],)))
        self.take()
        if t in ('true','false','null','nan','infinite','-infinite','-nan') or re.fullmatch(r'(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?',t): return self.post(Node('literal',(t,)))
        return self.post(Node('call',(t,())))
    def post(self,x):
        while True:
            if self.p().startswith('"') and isinstance(x,Node) and x.operation=='format':
                x=Node('format_template',(x.arguments[0],self.take())); continue
            if self.p().startswith('"'):
                x=Node('indexexpr',(x,Node('string',(self.take(),)))); continue
            if self.p()=='?': self.take(); x=Node('optional',(x,)); continue
            if self.p().startswith('.') and len(self.p())>1: x=Node('index',(x,self.take()[1:],False)); continue
            if self.p()=='.' and self.t[self.i+1].text.startswith('"'):
                self.take('.'); x=Node('indexexpr',(x,Node('string',(self.take(),)))); continue
            if self.p()=='.' and self.t[self.i+1].text=='[':
                self.take('.'); continue
            if self.p()=='[':
                self.take()
                if self.p()==']': self.take(); x=Node('iterate',(x,)); continue
                a=self.expr(0)
                if self.p()==':': self.take(); b=None if self.p()==']' else self.expr(0); self.take(']'); x=Node('slice',(x,a,b))
                else: self.take(']'); x=Node('indexexpr',(x,a))
                continue
            if self.p()=='(' and isinstance(x,Node) and x.operation=='call':
                name=x.arguments[0]; self.take(); args=[]
                if self.p()!=')':
                    args.append(self.expr(0))
                    while self.p() in (';',','): self.take(); args.append(self.expr(0))
                self.take(')'); x=Node('call',(name,tuple(args))); continue
            break
